create table wksp_doagmcp.ocg_group_events_2026 (
    event_id         number generated by default as identity not null enable,
    group_id         number not null enable,
    event_name       varchar2(200 byte) not null enable,
    event_type       varchar2(100 byte),
    start_date       date not null enable,
    end_date         date,
    city             varchar2(120 byte),
    venue            varchar2(200 byte),
    registration_url varchar2(400 byte),
    agenda_url       varchar2(400 byte),
    created_at       timestamp(6) with local time zone default systimestamp
);

alter table wksp_doagmcp.ocg_group_events_2026
    add constraint ocg_events_2026_end_chk
        check ( end_date is null
                or end_date >= start_date ) enable;

alter table wksp_doagmcp.ocg_group_events_2026
    add constraint ocg_events_2026_year_chk
        check ( start_date >= date '2026-01-01'
                and start_date < date '2027-01-01' ) enable;

alter table wksp_doagmcp.ocg_group_events_2026 add primary key ( event_id )
    using index enable;

